(() => {
 'use strict';const RI=window.RI,esc=RI.esc,statuses={open:'در انتظار پاسخ',answered:'پاسخ داده شده',closed:'بسته شده'},departments={sales:'فروش',finance:'مالی',technical:'فنی',account:'حساب کاربری',general:'عمومی'},categories={sales:'خرید و اشتراک',account:'حساب و ورود',payment:'کیف پول و پرداخت',editor:'طراحی و ویرایش',publication:'انتشار صفحه',other:'سایر موضوعات'};
 const metrics=[['total','همهٔ گفت‌وگوها','book'],['open','در انتظار پاسخ','clock'],['answered','پاسخ داده‌شده','check'],['closed','بسته‌شده','lock']];
 RI.registerPage('support',{title:'پشتیبانی',render(){return RI.pageHead({title:'گفت‌وگو با پشتیبانی',actions:'<button class="btn btn--primary" type="button" data-new-ticket>'+RI.icon('plus')+'تیکت تازه</button>'})+'<section data-activity-summary aria-label="خلاصهٔ تیکت‌ها">'+RI.activitySummary(metrics)+'</section><div id="support-tools"></div><div id="support-body" aria-live="polite"></div>';},mount(root,ctx){
  let alive=true,page=1,query='',status='',ticket=null,requestId=crypto.randomUUID(),timer,busy=false,serial=0,staff=false;
  const body=root.querySelector('#support-body'),tools=root.querySelector('#support-tools'),endpoint=()=>staff?'support?staff=1':'support';
  async function summary(){try{const result=await RI.dashboardRequest(endpoint());if(alive)root.querySelector('[data-activity-summary]').innerHTML=RI.activitySummary(metrics,result.summary);}catch{}}
  function filters(){tools.innerHTML='<div class="workspace-tools"><div class="field"><label class="field__label" for="ticket-search">جست‌وجوی تیکت</label><input class="input" type="search" id="ticket-search" value="'+esc(query)+'" placeholder="موضوع یا شناسه"></div><div class="field"><label class="field__label" for="ticket-status">وضعیت</label><select class="select" id="ticket-status"><option value="">همهٔ تیکت‌ها</option>'+Object.entries(statuses).map(([id,label])=>'<option value="'+id+'" '+(id===status?'selected':'')+'>'+label+'</option>').join('')+'</select></div>'+(RI.state.account.isAdmin?'<label class="check"><input type="checkbox" id="ticket-staff" '+(staff?'checked':'')+'>صندوق پشتیبانی</label>':'')+'</div>';}
  async function list(){ticket=null;const load=++serial;body.innerHTML='<p role="status">در حال دریافت تیکت‌ها…</p>';try{const result=await RI.dashboardRequest(endpoint()+(staff?'&':'?')+new URLSearchParams({page,q:query,status}));if(!alive||load!==serial)return;root.querySelector('[data-activity-summary]').innerHTML=RI.activitySummary(metrics,result.summary);body.innerHTML=result.rows.length?result.rows.map(t=>'<article class="history-row"><span class="row__ico">'+RI.icon('help')+'</span><div><b>'+esc(t.subject)+'</b><p>'+esc(categories[t.category]||'پشتیبانی')+(t.department?' · بخش '+esc(departments[t.department]||'عمومی'):'')+' · '+RI.date(Number(t.updated_at))+'</p><small class="ltr-inline">'+esc(t.id)+'</small></div><span class="chip">'+statuses[t.status]+'</span><button class="btn btn--soft btn--sm" type="button" data-ticket="'+t.id+'">گفت‌وگو'+RI.icon('chevL')+'</button></article>').join('')+RI.pagination(page,result.total,25):RI.empty({icon:'help',title:query||status?'تیکتی با این مشخصات نیست':'هنوز گفت‌وگویی شروع نشده',action:'<button class="btn btn--soft" type="button" data-new-ticket>ساخت تیکت</button>'});}catch(e){if(alive&&load===serial)body.innerHTML='<p role="alert">'+esc(e.message)+'</p><button class="btn btn--soft" type="button" data-retry>تلاش دوباره</button>';}}
  async function open(id){clearTimeout(timer);const load=++serial;tools.innerHTML='';body.innerHTML='<p role="status">در حال دریافت گفت‌وگو…</p>';try{const result=await RI.dashboardRequest(endpoint()+(staff?'&':'?')+'id='+encodeURIComponent(id));if(!alive||load!==serial)return;ticket=result;requestId=crypto.randomUUID();body.innerHTML='<div class="workspace-band"><button class="btn btn--ghost btn--sm" type="button" data-back>'+RI.icon('chevR')+'همهٔ تیکت‌ها</button><h2>'+esc(result.subject)+'</h2><span class="chip">'+statuses[result.status]+'</span>'+(result.department?'<span class="chip">بخش '+esc(departments[result.department]||'عمومی')+'</span>':'')+'<small class="ltr-inline"> '+esc(result.id)+'</small></div><div class="ticket-thread">'+result.messages.map(m=>'<article class="ticket-message '+(m.staff?'is-staff':'')+'"><b>'+(m.staff?'پشتیبانی رزومیت':'پیام شما')+'</b><p>'+esc(m.body)+'</p><small>'+RI.date(Number(m.created_at))+'</small></article>').join('')+'</div><section class="workspace-band">'+(result.status==='closed'?'<button class="btn btn--soft" type="button" data-ticket-status="open">باز کردن دوبارهٔ تیکت</button>':'<form id="ticket-reply"><div class="field"><label class="field__label" for="reply-body">پاسخ تازه</label><textarea class="textarea" id="reply-body" maxlength="6000" rows="4" required></textarea></div><div class="btnrow"><button class="btn btn--primary" type="submit">'+RI.icon('send')+'ارسال پاسخ</button><button class="btn btn--ghost" type="button" data-ticket-status="closed">بستن تیکت</button></div></form>')+'</section>'; }catch(e){if(alive&&load===serial)body.innerHTML='<p role="alert">'+esc(e.message)+'</p><button class="btn" data-back>بازگشت</button>';}}
  function create(){clearTimeout(timer);++serial;ticket=null;tools.innerHTML='';requestId=crypto.randomUUID();body.innerHTML='<form id="ticket-create" class="workspace-band"><div class="form-grid"><div class="field"><label class="field__label" for="ticket-subject">موضوع گفت‌وگو</label><input class="input" id="ticket-subject" maxlength="120" minlength="3" required></div><div class="field"><label class="field__label" for="ticket-category">بخش مربوط</label><select class="select" id="ticket-category">'+Object.entries(categories).map(([id,label])=>'<option value="'+id+'">'+label+'</option>').join('')+'</select></div></div><div class="field"><label class="field__label" for="ticket-message">چه اتفاقی افتاده؟</label><textarea class="textarea" id="ticket-message" maxlength="6000" minlength="10" rows="6" required></textarea><p class="field__hint">شناسهٔ پرداخت یا آدرس صفحه را بنویس؛ رمز عبور، کد پیامکی و اطلاعات کارت را نفرست.</p></div><div class="workspace-tools"><div class="field"><label class="field__label" for="ticket-priority">اولویت</label><select class="select" id="ticket-priority"><option value="normal">عادی</option><option value="high">اختلال جدی</option></select></div><button class="btn btn--primary" type="submit">ثبت تیکت</button><button class="btn btn--ghost" type="button" data-back>انصراف</button></div></form>';root.querySelector('#ticket-subject').focus();}
  const decorate=()=>{const form=body.querySelector('#ticket-create,#ticket-reply');if(form&&!form.querySelector('#ticket-files'))form.querySelector('.btnrow,.workspace-tools').insertAdjacentHTML('beforebegin',ResumeSupportFiles.input(staff||RI.hasSub()));if(ticket)body.querySelectorAll('.ticket-message').forEach((el,i)=>{if(!el.querySelector('[download]'))el.insertAdjacentHTML('beforeend',ResumeSupportFiles.links(ticket.messages[i]?.attachments,staff));});};
  const observer=new MutationObserver(decorate);observer.observe(body,{childList:true,subtree:true});
  RI.delegate(root,'click','[data-new-ticket]',create);RI.delegate(root,'click','[data-ticket]',(e,b)=>open(b.dataset.ticket));RI.delegate(root,'click','[data-back],[data-retry]',()=>{filters();list();});RI.delegate(root,'click','[data-page]',(e,b)=>{page=Number(b.dataset.page);list();});
  tools.addEventListener('input',e=>{if(e.target.id==='ticket-search'){query=e.target.value;page=1;clearTimeout(timer);timer=setTimeout(list,300);}});tools.addEventListener('change',e=>{if(e.target.id==='ticket-status')status=e.target.value;if(e.target.id==='ticket-staff')staff=e.target.checked;page=1;list();});
  root.addEventListener('submit',async e=>{
   const form=e.target;if(!['ticket-create','ticket-reply'].includes(form.id))return;e.preventDefault();if(busy||!form.reportValidity())return;
   const load=serial,scope=staff,paid=scope||RI.hasSub(),isNew=form.id==='ticket-create',payload=isNew?{subject:form.querySelector('#ticket-subject').value,category:form.querySelector('#ticket-category').value,priority:form.querySelector('#ticket-priority').value,body:form.querySelector('#ticket-message').value,requestId}:{id:ticket.id,body:form.querySelector('#reply-body').value,requestId};
   let feedback=form.querySelector('[data-send-status]');if(!feedback){feedback=document.createElement('p');feedback.dataset.sendStatus='';form.append(feedback);}feedback.setAttribute('role','status');feedback.textContent='در حال ارسال پیام…';form.setAttribute('aria-busy','true');
   const controls=[...form.elements].filter(el=>!el.disabled);controls.forEach(el=>el.disabled=true);busy=true;
   try{
    const attachments=await ResumeSupportFiles.read(form.querySelector('#ticket-files'),paid);if(!alive||load!==serial)return;
    const result=await RI.dashboardRequest(isNew?'support':'support/reply'+(scope?'?staff=1':''),{...payload,attachments});
    if(alive&&load===serial){RI.toast('پیام ثبت شد');await open(result.id);summary();}
   }catch(error){if(alive&&load===serial){feedback.setAttribute('role','alert');feedback.textContent=error.message;}}
   finally{busy=false;controls.forEach(el=>el.disabled=false);form.removeAttribute('aria-busy');}
  });
  RI.delegate(root,'click','[data-ticket-status]',async(e,b)=>{const load=serial,id=ticket.id,scope=staff;b.disabled=true;try{await RI.dashboardRequest('support/status'+(scope?'?staff=1':''),{id,status:b.dataset.ticketStatus});if(alive&&load===serial){open(id);summary();}}catch(error){if(alive&&load===serial)RI.toast(error.message,{kind:'error'});b.disabled=false;}});
  const id=new URLSearchParams(location.search).get('ticket');if(id){open(id);summary();}else if(ctx.opts?.tab==='new'){create();summary();}else{filters();list();}return()=>{alive=false;clearTimeout(timer);observer.disconnect();};
 }});
})();
